function parseCsv(text){const rows=[];let row=[],cell="",quoted=false;for(let i=0;i<text.length;i+=1){const char=text[i],next=text[i+1];if(char==='"'&&quoted&&next==='"'){cell+='"';i+=1;}else if(char==='"')quoted=!quoted;else if(char===','&&!quoted){row.push(cell.trim());cell="";}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&next==='\n')i+=1;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell="";}else cell+=char;}row.push(cell.trim());if(row.some(Boolean))rows.push(row);return rows;}
