const formatTimeRange=value=>String(value).replace(/\b([01]\d|2[0-3])([0-5]\d)\s*-\s*([01]\d|2[0-3])([0-5]\d)/g,(_,startHour,startMinute,endHour,endMinute)=>{const clock=(hour,minute)=>{const numeric=Number(hour);return (numeric%12||12)+":"+minute+" "+(numeric>=12?"PM":"AM");};return clock(startHour,startMinute)+" - "+clock(endHour,endMinute);});

function buildNudge(guide,lvoState,state={},fallback) {
  const charge=value(guide,"Charge Entry"),completion=value(guide,"Consult Completion Rule");
  const ctPerfusion=value(guide,"CT Perfusion"),ai=value(guide,"AI"),order=value(guide,"Order Entry");
  const orderSet=value(guide,"Order Set Name"),noteTitle=value(guide,"Required Note Title");
  const rounding=value(guide,"When Do We Round?"),timing=value(guide,"Rounding Timing");

  // Hard stops always outrank advisories and routine next-step guidance.
  if(state.signoff&&charge==="Yes"&&!state.chargeEntered)return {title:"Record the required encounter charge",copy:"This hospital requires the tele-neurology encounter charge before sign-off.",steps:["Record the encounter charge.","Return to Sign-off and complete the consult."],source:"Hard stop · Sign-off · Charge Entry"};
  if(state.signoff&&completion)return {title:"Obtain confirmation before sign-off",copy:completion,steps:["Confirm the plan with the hospital provider.","Then complete the consult."],source:"Hard stop · Sign-off · Consult Completion Rule"};

  // These match the field-event nudges in the uploaded scenario table.
  if(state.rounding)return {title:"Check rounding eligibility",copy:(rounding||"Rounding schedule not specified.")+(timing?" Window: "+formatTimeRange(timing)+".":""),steps:["Confirm this is an eligible rounding day and time.","Follow the hospital's rounding-order rule."],source:"Info · Rounding encounter opened"};
  if(state.note)return {title:"Use the hospital's required note title",copy:noteTitle?"Create the note as “"+noteTitle+"”.":"No required note title is specified in this guide.",steps:["Create or verify the consult note.","Use the required title before sign-off."],source:"Advisory · Note title"};
  if(state.recommendation)return {title:"Apply the thrombolytic order workflow",copy:order||"Order-entry guidance is not provided.",steps:[orderSet?"Use the listed local order set: "+orderSet:"Do not invent an order set.","Follow the local thrombolytic mixing guidance."],source:"Advisory · Thrombolytic given"};
  if(lvoState==="yes")return {title:"Follow the LVO escalation pathway",copy:value(guide,"LVO Protocol")||"No LVO pathway is specified in this guideline.",steps:["Notify the responsible ED provider.","Follow the transfer or thrombectomy routing listed for this hospital."],source:"Advisory · LVO present = Yes"};
  if(state.imaging)return {title:"Review imaging support after CTA",copy:"CT perfusion: "+(ctPerfusion||"not provided")+". AI: "+(ai||"not provided")+".",steps:["Use only capabilities listed for this hospital.","Do not assume unavailable services are present."],source:"Info · CTA done = Yes"};

  // No trigger means no alert condition; show the one chronological workflow prompt instead.
  return fallback||{title:"Continue the hospital workflow",copy:"No state-driven nudge is active.",steps:[],source:"Next workflow step"};
}

